## Why This Is Asked
Tests understanding of combining Context with a small Redux-like store, debounce patterns, and memoized rendering for performance.

## Key Concepts
- useReducer + Context for lightweight global store
- Debounce with useEffect
- Memoized selectors with useMemo
- React.memo for granular re-render control
- Cleanup on unmount and dependency changes

## Code Example
```javascript
// store.js
import React from 'react'

export const AppConfigContext = React.createContext({ apiEndpoint: '/api', debounce: 300 })

const initialState = { query: '', results: [] }

function reducer(state, action) {
  switch (action.type) {
    case 'SET_QUERY':
      return { ...state, query: action.payload }
    case 'SET_RESULTS':
      return { ...state, results: action.payload }
    default:
      return state
  }
}

export function useStore() {
  const [state, dispatch] = React.useReducer(reducer, initialState)
  const actions = React.useMemo(() => ({
    setQuery: (q) => dispatch({ type: 'SET_QUERY', payload: q }),
    setResults: (r) => dispatch({ type: 'SET_RESULTS', payload: r })
  }), [])
  return { state, actions }
}
```

```javascript
// DebouncedSearchInput.js
import React from 'react'
export function DebouncedSearchInput({ value, onChange, delay = 300 }) {
  const [local, setLocal] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => onChange(local), delay)
    return () => clearTimeout(id)
  }, [local, delay, onChange])
  React.useEffect(() => setLocal(value), [value])
  return <input value={local} onChange={(e) => setLocal(e.target.value)} />
}
```

